exercises.solution:
SELECT name, hired_on FROM employees
WHERE hired_on >= '2022-01-01' AND hired_on < '2023-01-01'
ORDER BY hired_on;

SELECT f.id, f.flight_no
FROM flights f JOIN airports a ON a.code = f.origin
WHERE (f.dep_at AT TIME ZONE a.tz)::date = date '2025-03-10';

SELECT e.name AS employee, m.name AS manager
FROM employees e
LEFT JOIN employees m ON m.id = e.manager_id;

SELECT e.name AS employee, e.salary, m.name AS manager, m.salary AS manager_salary
FROM employees e JOIN employees m ON m.id = e.manager_id
WHERE e.salary > m.salary;

SELECT origin, day, departures FROM (
  SELECT f.origin, (f.dep_at AT TIME ZONE a.tz)::date AS day, count(*) AS departures,
         rank() OVER (PARTITION BY f.origin ORDER BY count(*) DESC) AS r
  FROM flights f JOIN airports a ON a.code = f.origin
  GROUP BY f.origin, day
) t WHERE r = 1;

WITH RECURSIVE routes AS (
  SELECT DISTINCT origin, dest FROM flights WHERE status <> 'cancelled'
), walk AS (
  SELECT dest AS code, 1 AS legs, ARRAY['DEL'::bpchar, dest] AS seen FROM routes WHERE origin = 'DEL'
  UNION ALL
  SELECT r.dest, w.legs + 1, w.seen || r.dest
  FROM walk w JOIN routes r ON r.origin = w.code
  WHERE r.dest <> ALL (w.seen)
)
SELECT code, min(legs) AS legs FROM walk WHERE code <> 'DEL' GROUP BY code;

SELECT department, name, salary FROM (
  SELECT d.name AS department, e.name, e.salary,
         dense_rank() OVER (PARTITION BY e.dept_id ORDER BY e.salary) AS r
  FROM employees e JOIN departments d ON d.id = e.dept_id
) t WHERE r <= 3;

SELECT sensor_id, ts AS gap_from, next_ts AS gap_to,
       (extract(epoch FROM next_ts - ts) / 600)::int - 1 AS missing
FROM (
  SELECT sensor_id, ts, lead(ts) OVER (PARTITION BY sensor_id ORDER BY ts) AS next_ts FROM readings
) t
WHERE next_ts - ts > interval '10 minutes';

SELECT decade, title, loans FROM (
  SELECT b.published / 10 * 10 AS decade, b.title, count(*) AS loans,
         rank() OVER (PARTITION BY b.published / 10 * 10 ORDER BY count(*) DESC) AS r
  FROM books b JOIN loans l ON l.book_id = b.id
  GROUP BY b.id, b.title, b.published
) t WHERE r = 1;

SELECT m.name AS member, l.loaned_on,
       l.loaned_on - lag(l.loaned_on) OVER (PARTITION BY l.member_id ORDER BY l.loaned_on) AS days_since_prev
FROM loans l JOIN members m ON m.id = l.member_id;

SELECT d::date AS day, (d::date + time '18:00') AT TIME ZONE 'America/New_York' AS dep_utc
FROM generate_series(date '2025-03-07', date '2025-03-11', interval '1 day') AS d
ORDER BY day;

